// HasCi applies the HasEdge predicate on the "ci" edge.
func HasCi() predicate.CiRecords {
	return predicate.CiRecords(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CiTable, CiColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCiWith applies the HasEdge predicate on the "ci" edge with a given conditions (other predicates).
func HasCiWith(preds ...predicate.Cis) predicate.CiRecords {
	return predicate.CiRecords(func(s *sql.Selector) {
		step := newCiStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasCiType applies the HasEdge predicate on the "ci_type" edge.
func HasCiType() predicate.CiRecords {
	return predicate.CiRecords(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, CiTypeTable, CiTypeColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCiTypeWith applies the HasEdge predicate on the "ci_type" edge with a given conditions (other predicates).
func HasCiTypeWith(preds ...predicate.CiType) predicate.CiRecords {
	return predicate.CiRecords(func(s *sql.Selector) {
		step := newCiTypeStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CiRecords) predicate.CiRecords {
	return predicate.CiRecords(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CiRecords) predicate.CiRecords {
	return predicate.CiRecords(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CiRecords) predicate.CiRecords {
	return predicate.CiRecords(sql.NotPredicates(p))
}
